-- Read-only metadata. No user rows, credentials, token values or object names.
select jsonb_build_object('relations',(select jsonb_agg(r order by r.schema_name,r.table_name) from (select n.nspname as schema_name,c.relname as table_name,c.relkind,c.relrowsecurity as rls_enabled,(select jsonb_agg(jsonb_build_object('name',a.attname,'type',pg_catalog.format_type(a.atttypid,a.atttypmod)) order by a.attnum) from pg_attribute a where a.attrelid=c.oid and a.attnum>0 and not a.attisdropped) as columns,(select coalesce(jsonb_agg(pg_get_constraintdef(k.oid) order by k.conname),'[]'::jsonb) from pg_constraint k where k.conrelid=c.oid and k.contype='f') as foreign_keys from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname in ('public','private','auth','storage') and c.relkind in ('r','p','v','m')) r),'buckets',(select jsonb_agg(jsonb_build_object('id',b.id,'public',b.public) order by b.id) from storage.buckets b)) as catalog;
